const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

// 상태 셋이 서로 얽혀 있습니다. 동작 하나마다 셋을 함께 고쳐야 합니다.
const Cart = () => {
  const [count, setCount] = useState(0);
  const [total, setTotal] = useState(0);
  const [last, setLast] = useState('아직 없음');

  const add = () => {
    setCount(count + 1);
    setTotal(total + 189000);
    setLast('담기');
  };

  const remove = () => {
    if (count === 0) return;
    setCount(count - 1);
    setTotal(total - 189000);
    setLast('빼기');
  };

  const clear = () => {
    setCount(0);
    setTotal(0);
    setLast('비우기');
  };

  return (
    <div className="cart">
      <p className="summary">{count}개 · {total}원</p>
      <p className="log">마지막 동작: {last}</p>
      <div className="row">
        <button className="add" type="button" onClick={add}>담기</button>
        <button className="remove" type="button" onClick={remove}>빼기</button>
        <button className="clear" type="button" onClick={clear}>비우기</button>
      </div>
    </div>
  );
};

root.render(<Cart />);

