const { useReducer } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const PRICE = 189000;

const reducer = (state, action) => {
  if (action.type === 'add') {
    return { count: state.count + 1, total: state.total + PRICE, last: '담기' };
  }

  if (action.type === 'remove') {
    if (state.count === 0) return state;
    return null; // ← 여기를 채우세요
  }

  if (action.type === 'clear') {
    return { count: 0, total: 0, last: '비우기' };
  }

  return state;
};

const Cart = () => {
  const [state, dispatch] = useReducer(reducer, { count: 0, total: 0, last: '아직 없음' });

  return (
    <div className="cart">
      <p className="summary">{state.count}개 · {state.total}원</p>
      <p className="log">마지막 동작: {state.last}</p>
      <div className="row">
        <button className="add" type="button" onClick={() => dispatch({ type: 'add' })}>담기</button>
        <button className="remove" type="button" onClick={() => dispatch({ type: 'remove' })}>빼기</button>
        <button className="clear" type="button" onClick={() => dispatch({ type: 'clear' })}>비우기</button>
      </div>
    </div>
  );
};

root.render(<Cart />);

